import * as THREE from 'three';
import { MovementCfg as C } from './config.js';
import { approach, smooth } from './spring.js';
import type { Input } from './input.js';
import type { World } from './world.js';

/** Movement states, same names as the Roblox version. */
export type MoveState = 'Idle' | 'Walk' | 'Crouch' | 'Sprint' | 'TacSprint' | 'Slide' | 'Air';

/**
 * MW2019 / Warzone movement — walk, crouch, sprint, tactical sprint (double-tap Shift),
 * slide (crouch while sprinting) and slide-hop. Port of `Movement.luau`.
 */
export class Movement {
  pos = new THREE.Vector3();
  vel = new THREE.Vector3();
  state: MoveState = 'Idle';
  speed = 0;
  grounded = true;
  airTime = 0;
  eyeHeight = C.eye.stand;
  alpha = { sprint: 0, tac: 0, slide: 0, crouch: 0 };
  isSprinting = false;
  sprintBlocked = false;
  crouched = false;
  tac = false;
  tacTimer = 0;
  private tacArmedUntil = 0;
  private lastShiftTap = 0;
  sliding = false;
  slideSpeed = 0;
  slideDir = new THREE.Vector3();
  slideCooldown = 0;
  private carry = 0;
  private curWalk = C.walkSpeed;
  private lastVy = 0;
  /** Horizontal lunge override (melee): direction * speed applied until `lungeUntil`. */
  private lungeVel = new THREE.Vector3();
  private lungeUntil = 0;
  onLand?: (impact: number) => void;
  onSlide?: () => void;
  onJump?: () => void;

  /** @param world collision world */
  constructor(private world: World) {}

  /**
   * Starts a short forward lunge that overrides normal ground control (used by the melee swing).
   * @param dir horizontal direction (normalized)
   * @param speed studs per second
   * @param until time (seconds) the lunge ends
   */
  lunge(dir: THREE.Vector3, speed: number, until: number) {
    this.lungeVel.set(dir.x * speed, 0, dir.z * speed);
    this.lungeUntil = until;
  }

  /**
   * Places the player at a spawn point.
   * @param p spawn position
   */
  spawn(p: THREE.Vector3) {
    this.pos.copy(p);
    this.vel.set(0, 0, 0);
    this.sliding = this.isSprinting = this.tac = this.crouched = false;
    this.carry = 0;
    this.curWalk = C.walkSpeed;
  }

  get height() {
    return this.sliding ? C.height.slide : this.crouched ? C.height.crouch : C.height.stand;
  }

  private crouchPressed() {
    if (this.sliding) return;
    const canSlide = this.isSprinting && this.grounded && this.speed >= C.slideMinSpeed && this.slideCooldown <= 0;
    if (canSlide) this.startSlide();
    else {
      if (this.crouched && !this.canStand()) return;
      this.crouched = !this.crouched;
    }
  }

  private canStand() {
    const p = this.pos.clone();
    const r = C.radius;
    return !this.world.solids.some((s) => p.x + r > s.min.x && p.x - r < s.max.x && p.z + r > s.min.z && p.z - r < s.max.z && p.y + C.height.stand > s.min.y && p.y + 0.2 < s.max.y);
  }

  private startSlide() {
    const v = new THREE.Vector3(this.vel.x, 0, this.vel.z);
    this.slideDir.copy(v.lengthSq() > 0.01 ? v.normalize() : this.slideDir);
    this.slideSpeed = Math.min(Math.max(Math.hypot(this.vel.x, this.vel.z) * C.slideBoost, C.slideSpeed), C.slideMax);
    this.sliding = true;
    this.crouched = true;
    this.tac = false;
    this.isSprinting = false;
    this.onSlide?.();
  }

  private endSlide(jumped: boolean) {
    if (!this.sliding) return;
    this.sliding = false;
    this.slideCooldown = C.slideCooldown;
    if (jumped) {
      this.crouched = false;
      this.carry = this.slideSpeed * 0.9; // slide-hop keeps momentum
    }
  }

  /**
   * Steps movement.
   * @param dt delta seconds
   * @param yaw camera yaw (radians)
   * @param input input state
   * @param speedMult weapon / ADS speed multiplier
   * @param now current time (seconds)
   */
  update(dt: number, yaw: number, input: Input, speedMult: number, now: number) {
    // input edges
    if (input.wasPressed('ShiftLeft')) {
      if (now - this.lastShiftTap < C.tacDoubleTap) this.tacArmedUntil = now + 0.6;
      this.lastShiftTap = now;
    }
    if (input.wasPressed('KeyC') || input.wasPressed('ControlLeft')) this.crouchPressed();
    const jumpPressed = input.wasPressed('Space');

    this.speed = Math.hypot(this.vel.x, this.vel.z);
    this.slideCooldown = Math.max(0, this.slideCooldown - dt);

    const iv = input.moveVector();
    const sin = Math.sin(yaw);
    const cos = Math.cos(yaw);
    // forward = (-sin, 0, -cos), right = (cos, 0, -sin)
    const moveDir = new THREE.Vector3(iv.x * cos + iv.z * sin, 0, -iv.x * sin + iv.z * cos);
    const forwardness = iv.mag > 0.1 ? -iv.z : 0;

    // sprint / tactical sprint
    const wantsSprint = input.isDown('ShiftLeft');
    const canSprint = wantsSprint && !this.sprintBlocked && !this.sliding && (this.grounded || this.isSprinting) && forwardness > 0.5;
    if (canSprint) {
      if (!this.isSprinting) {
        if (this.crouched && !this.canStand()) {
          /* stay crouched */
        } else {
          this.isSprinting = true;
          this.crouched = false;
          if (now < this.tacArmedUntil) {
            this.tac = true;
            this.tacTimer = C.tacTime;
            this.tacArmedUntil = 0;
          }
        }
      }
      if (this.tac) {
        this.tacTimer -= dt;
        if (this.tacTimer <= 0) this.tac = false;
      }
    } else {
      this.isSprinting = false;
      this.tac = false;
    }

    // slide
    if (this.sliding) {
      this.slideSpeed = THREE.MathUtils.clamp(this.slideSpeed - C.slideFriction * dt, 0, C.slideMax);
      if (moveDir.lengthSq() > 0.01) {
        const dd = this.slideDir.clone().lerp(moveDir.clone().normalize(), THREE.MathUtils.clamp(C.slideSteer * dt, 0, 1));
        if (dd.length() > 0.05) this.slideDir.copy(dd.normalize());
      }
      if (this.airTime > 0.2) {
        this.carry = this.slideSpeed;
        this.endSlide(false);
      } else if (this.slideSpeed < C.slideEndSpeed) this.endSlide(false);
    }

    // jump
    if (jumpPressed) {
      if (this.sliding) this.endSlide(true);
      else if (this.crouched && this.canStand()) this.crouched = false;
      if (this.grounded) {
        this.vel.y = Math.sqrt(2 * C.gravity * C.jumpHeight);
        this.grounded = false;
        this.onJump?.();
      }
    }

    // target speed
    let base: number;
    if (this.tac) base = C.tacSpeed;
    else if (this.isSprinting) base = C.sprintSpeed;
    else if (this.crouched) base = C.crouchSpeed * speedMult;
    else base = C.walkSpeed * speedMult;

    let target: number;
    if (this.sliding) target = this.slideSpeed;
    else if (!this.grounded) {
      this.carry = Math.max(0, this.carry - 3 * dt);
      target = Math.max(base, this.carry);
    } else {
      this.carry = 0;
      target = base;
    }
    if (this.sliding) this.curWalk = target;
    else this.curWalk = approach(this.curWalk, target, (target > this.curWalk ? C.accel : C.decel) * dt);

    const dir = this.sliding ? this.slideDir : moveDir;
    const desired = dir.clone().multiplyScalar(this.curWalk);
    if (this.grounded || this.sliding) {
      // humanoid-like snappy ground control
      const k = 1 - Math.exp(-(dir.lengthSq() > 0 ? 18 : 14) * dt);
      this.vel.x += (desired.x - this.vel.x) * k;
      this.vel.z += (desired.z - this.vel.z) * k;
    } else {
      const k = 1 - Math.exp(-4 * dt);
      if (dir.lengthSq() > 0) {
        this.vel.x += (desired.x - this.vel.x) * k;
        this.vel.z += (desired.z - this.vel.z) * k;
      }
    }
    this.vel.y -= C.gravity * dt;
    if (this.lungeUntil > 0) {
      if (now < this.lungeUntil && !this.sliding) {
        this.vel.x = this.lungeVel.x;
        this.vel.z = this.lungeVel.z;
      } else {
        // lunge over: stop dead instead of coasting into the target
        this.vel.x = 0;
        this.vel.z = 0;
        this.lungeUntil = 0;
      }
    }

    const wasGrounded = this.grounded;
    this.grounded = this.world.move(this.pos, this.vel, dt, C.radius, this.height, this.grounded ? C.stepHeight : 0.3);
    if (this.grounded && !wasGrounded && this.lastVy < -22) this.onLand?.(-this.lastVy);
    this.airTime = this.grounded ? 0 : this.airTime + dt;
    this.lastVy = this.vel.y;
    if (this.grounded && this.vel.y < 0) this.vel.y = 0;

    if (this.sliding) this.state = 'Slide';
    else if (!this.grounded) this.state = 'Air';
    else if (this.tac) this.state = 'TacSprint';
    else if (this.isSprinting) this.state = 'Sprint';
    else if (this.crouched) this.state = 'Crouch';
    else if (this.speed > 1) this.state = 'Walk';
    else this.state = 'Idle';

    const A = this.alpha;
    A.sprint = smooth(A.sprint, this.isSprinting ? 1 : 0, 10, dt);
    A.tac = smooth(A.tac, this.tac ? 1 : 0, 8, dt);
    A.slide = smooth(A.slide, this.sliding ? 1 : 0, 12, dt);
    A.crouch = smooth(A.crouch, this.crouched && !this.sliding ? 1 : 0, 10, dt);
    const eyeT = this.sliding ? C.eye.slide : this.crouched ? C.eye.crouch : C.eye.stand;
    this.eyeHeight = smooth(this.eyeHeight, eyeT, 14, dt);
  }
}
